#include <iostream>
#include <memory>
#include <string>

struct Servidor {
    std::string host;
    int porta;
};

int main() {
    auto srv = std::make_unique<Servidor>("localhost", 8080);
    std::cout << srv->host << ":" << srv->porta << "\n";
    return 0; // srv libera a memória automaticamente aqui!
}

